import { ref, onMounted } from 'vue'
import { useToast } from 'primevue/usetoast'
import { useFeeProfileStore } from '@/stores/feeProfiles'
import Dialog from 'primevue/dialog'
import Button from 'primevue/button'
import InputText from 'primevue/inputtext'
import InputNumber from 'primevue/inputnumber'
import SelectButton from 'primevue/selectbutton'
import ToggleSwitch from 'primevue/toggleswitch'

const props = defineProps({ visible: Boolean })
const emit = defineEmits(['update:visible'])

const toast = useToast()
const store = useFeeProfileStore()

const editing = ref(null)   // null = closed, 'new' or profile object
const form = ref(defaultForm())

function defaultForm() {
  return { name: '', type: 'percent', value: null, minFee: 0, currency: 'USD', isDefault: false }
}

onMounted(() => { if (!store.profiles.length) store.fetchProfiles() })

function openNew() { editing.value = 'new'; form.value = defaultForm() }
function openEdit(p) { editing.value = p; form.value = { ...p } }
function closeEdit() { editing.value = null }

async function save() {
  if (!form.value.name || form.value.value == null) {
    toast.add({ severity: 'warn', summary: 'Name and fee value required', life: 2000 }); return
  }
  try {
    if (editing.value === 'new') {
      await store.createProfile(form.value)
      toast.add({ severity: 'success', summary: 'Fee profile created', life: 2000 })
    } else {
      await store.updateProfile(editing.value._id, form.value)
      toast.add({ severity: 'success', summary: 'Updated', life: 2000 })
    }
    closeEdit()
  } catch (err) {
    toast.add({ severity: 'error', summary: err.message, life: 3000 })
  }
}

async function remove(p) {
  try {
    await store.deleteProfile(p._id)
    toast.add({ severity: 'success', summary: 'Deleted', life: 2000 })
  } catch (err) {
    toast.add({ severity: 'error', summary: err.message, life: 3000 })
  }
}
</script>

<template>
  <Dialog
    :visible="visible"
    @update:visible="emit('update:visible', $event)"
    modal
    header="Fee Profiles"
    :style="{ width: '95vw', maxWidth: '440px' }"
    :draggable="false"
  >
    <!-- Profile list -->
    <div v-if="!editing">
      <div v-if="store.loading" class="text-muted">Loading...</div>

      <div v-else-if="!store.profiles.length" class="empty">
        <p class="text-muted">No fee profiles yet</p>
      </div>

      <div v-else class="profile-list">
        <div v-for="p in store.profiles" :key="p._id" class="profile-row">
          <div class="profile-info">
            <span class="profile-name">
              {{ p.name }}
              <span v-if="p.isDefault" class="default-badge">Default</span>
            </span>
            <span class="profile-detail text-muted">
              {{ p.type === 'percent' ? `${p.value}%` : `${p.currency} ${p.value} flat` }}
              <span v-if="p.minFee"> · min {{ p.minFee }}</span>
            </span>
          </div>
          <div class="profile-actions">
            <Button icon="pi pi-pencil" text rounded size="small" @click="openEdit(p)" />
            <Button icon="pi pi-trash" text rounded size="small" severity="danger" @click="remove(p)" />
          </div>
        </div>
      </div>

      <Button label="Add Profile" icon="pi pi-plus" fluid class="mt" @click="openNew" />
    </div>

    <!-- Edit / Create form -->
    <div v-else class="fee-form">
      <div class="form-header">
        <span class="form-title">{{ editing === 'new' ? 'New Profile' : 'Edit Profile' }}</span>
        <Button icon="pi pi-arrow-left" text rounded size="small" @click="closeEdit" />
      </div>

      <div class="field">
        <label>Vendor name</label>
        <InputText v-model="form.name" placeholder="e.g. IBI, Meitav, Interactive Brokers" fluid />
      </div>

      <div class="field">
        <label>Fee type</label>
        <SelectButton v-model="form.type" :options="['percent', 'flat']" fluid />
      </div>

      <div class="fields-row">
        <div class="field">
          <label>{{ form.type === 'percent' ? 'Fee %' : 'Flat fee' }}</label>
          <InputNumber
            v-model="form.value"
            :suffix="form.type === 'percent' ? '%' : ''"
            :min="0"
            :max-fraction-digits="4"
            :placeholder="form.type === 'percent' ? '0.1' : '5'"
            fluid
          />
        </div>
        <div class="field">
          <label>Min fee</label>
          <InputNumber v-model="form.minFee" :min="0" :max-fraction-digits="2" placeholder="0" fluid />
        </div>
      </div>

      <div class="field">
        <label>Currency</label>
        <SelectButton v-model="form.currency" :options="['USD', 'ILS', 'EUR']" />
      </div>

      <div class="field-row-inline">
        <label>Set as default</label>
        <ToggleSwitch v-model="form.isDefault" />
      </div>

      <Button label="Save" fluid @click="save" />
    </div>
  </Dialog>
</template>

